                <th className="px-5 py-4 font-medium">Erfasst</th>
                <th className="px-5 py-4 font-medium">Confidence</th>
              </tr>
            </thead>
            <tbody>
              {lottoDemoCases.map((c) => (
                <tr
                  key={c.case_id}
                  className="border-b border-border last:border-0 transition-colors hover:bg-muted/60"
